// Prepare input for Claude Call 1 — Anomaly Classification
const config = $('Set Config').item.json;
const deploymentRecords = $('Read Deployment Record').item.json.records;
const signalRecords = $('Read Signal Feeds').item.json.records;

if (!deploymentRecords || deploymentRecords.length === 0) {
  throw new Error('No deployment record found for: ' + config.deployment_id);
}

const deployment = deploymentRecords[0].fields;
const signals = signalRecords.map(r => r.fields);

const userMessage = `Deployment Record:\n${JSON.stringify(deployment, null, 2)}\n\nSignal Deviations (measured 4 hours post-release):\n${JSON.stringify(signals, null, 2)}\n\nClassify the anomaly. Return JSON only.`;

const systemPrompt = "You are a client impact analyst at a fintech company. You receive post-deployment signal data showing deviations from baseline across multiple signal types.\n\nClassify the anomaly across four dimensions:\n\n1. affected_flow — the specific product flow or feature where the failure is occurring\n2. affected_segment — the specific client segment impacted\n3. signal_severity — one of: low, medium, high, critical\n4. anomaly_type — one of: Bug, Degradation, Intentional Restriction, New Baseline, Unknown\n\nAnomaly type guidance:\n- Use Bug when signals suggest an unintended system failure with historical precedent likely\n- Use Degradation when signals suggest gradual performance decline rather than a sudden break\n- Use Intentional Restriction when signals suggest access limitations that may be by design — phased rollouts, invite-only launches, eligibility gates. Key indicator: support contacts spike but error_rate is low or absent; affected segment is narrow and new\n- Use New Baseline when the product area has no historical precedent and you cannot classify confidently\n- Use Unknown when classification is not possible from available signals\n\nAlso return: warrants_pattern_matching (boolean) — true if anomaly_type is Bug or Degradation and signal_severity is medium or above.\n\nReturn valid JSON only. No explanation text outside the JSON.\n\nOutput fields: affected_flow (string), affected_segment (string), signal_severity (low/medium/high/critical), anomaly_type (Bug/Degradation/Intentional Restriction/New Baseline/Unknown), warrants_pattern_matching (boolean), classification_notes (one sentence on the primary classification signal).";

return [{
  json: {
    deployment,
    signals,
    call1_user_message: userMessage,
    call1_system_prompt: systemPrompt,
    airtable_base_id: config.airtable_base_id,
    airtable_api_key: config.airtable_api_key,
    anthropic_api_key: config.anthropic_api_key,
    deployment_id: config.deployment_id
  }
}];

// Parse Claude Call 1 response and prepare Call 2 input
const prev = $('Prepare Call 1 Input').item.json;
const response = $input.item.json;

const content = response.content[0].text;
let anomalyClassification;

try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  anomalyClassification = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Call 1 response: ' + content);
}

console.log('Call 1 result — severity:', anomalyClassification.signal_severity);
console.log('Anomaly type:', anomalyClassification.anomaly_type);
console.log('Warrants pattern matching:', anomalyClassification.warrants_pattern_matching);

return [{
  json: {
    anomaly_classification: anomalyClassification,
    deployment: prev.deployment,
    deployment_id: prev.deployment_id,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key,
    anthropic_api_key: prev.anthropic_api_key
  }
}];

// Prepare input for Claude Call 2 — Historical Pattern Matching
const prev = $('Parse Call 1').item.json;
const incidentsResponse = $input.item.json;

const incidents = incidentsResponse.records.map(r => r.fields);

const userMessage = `Current Anomaly Classification:\n${JSON.stringify(prev.anomaly_classification, null, 2)}\n\nHistorical Incident Database (full):\n${JSON.stringify(incidents, null, 2)}\n\nFind the closest historical match. Return JSON only.`;

const systemPrompt = "You are a pattern-matching system for a fintech engineering team. You have access to a database of past incidents. Given an anomaly classification from a post-deployment signal analysis, identify the closest historical match.\n\nCalculate match_confidence (0-100) using:\n- Signal type overlap: 40% weight — how many of the same signal types are elevated?\n- Affected segment overlap: 30% weight — same account type, same user segment?\n- Affected flow overlap: 30% weight — same product area and flow step?\n\nRules:\n- If anomaly_type is Intentional Restriction or New Baseline and no strong match exists, confirm that type and set match_confidence below 60\n- If anomaly_type is Bug or Degradation, find the best match even if imperfect\n- A match on all three dimensions (signal type + segment + flow) should produce match_confidence 75+\n- A near-structural twin (same everything) should produce match_confidence 85+\n\nReturn valid JSON only. No explanation text outside the JSON.\n\nOutput fields: match_id (string or null), match_confidence (0-100 integer), matching_signals (array of signal type strings), probable_root_cause (string — specific technical hypothesis based on historical match), historical_resolution (string — what was done to fix it previously), anomaly_type_confirmed (Bug/Degradation/Intentional Restriction/New Baseline/Unknown).";

return [{
  json: {
    anomaly_classification: prev.anomaly_classification,
    deployment: prev.deployment,
    deployment_id: prev.deployment_id,
    incidents,
    call2_user_message: userMessage,
    call2_system_prompt: systemPrompt,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key,
    anthropic_api_key: prev.anthropic_api_key
  }
}];

// Parse Claude Call 2 response and prepare Call 3 input
const prev = $('Prepare Call 2 Input').item.json;
const response = $input.item.json;

const content = response.content[0].text;
let patternMatch;

try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  patternMatch = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Call 2 response: ' + content);
}

console.log('Call 2 result — match_id:', patternMatch.match_id, '| confidence:', patternMatch.match_confidence);
console.log('Anomaly type confirmed:', patternMatch.anomaly_type_confirmed);

const userMessage = `Deployment Record:\n${JSON.stringify(prev.deployment, null, 2)}\n\nAnomaly Classification (Call 1 output):\n${JSON.stringify(prev.anomaly_classification, null, 2)}\n\nHistorical Pattern Match (Call 2 output):\n${JSON.stringify(patternMatch, null, 2)}\n\nGenerate the impact brief. Return JSON only.`;

const systemPrompt = "You are generating an impact brief for an engineering and product team at a fintech company. The brief will be reviewed by a human who must make a rollback, escalation, or accept decision.\n\nBe specific and actionable. Do not speculate beyond the evidence. State confidence level and anomaly type explicitly. The human makes the final decision — make that decision as informed as possible.\n\nConfidence score calculation (weighted composite):\n- Signal Strength (40%): number of independent signals elevated + magnitude. Social trust contributes at half weight of internal signals.\n- Segment Specificity (30%): how precisely is the anomaly localized? Broad spike = low score. Specific version + account combo + flow step = high score.\n- Historical Match Quality (30%): how closely does the current pattern match a past incident? Signal type match only = low. Signal + segment + flow + resolution pattern = high.\n\nConfidence bands:\n- 95-100: Critical\n- 80-94: High\n- 60-79: Medium\n- below 60: Low\n\nSet low_confidence_flag to true if: confidence_score < 60 OR anomaly_type is Intentional Restriction OR anomaly_type is New Baseline.\n\nReturn valid JSON only. No explanation text outside the JSON.\n\nOutput fields: confidence_score (integer 0-100), confidence_band (Low/Medium/High/Critical), anomaly_type (Bug/Degradation/Intentional Restriction/New Baseline/Unknown), affected_flow (string), affected_segment (string), affected_users_est (integer), signal_summary (array of objects with signal_type/direction/magnitude/note), pattern_match_summary (2-4 sentence plain-language summary of historical match), pr_to_review (PR number string or null), recommended_action (string — specific, actionable, one sentence), low_confidence_flag (boolean), full_brief_text (complete formatted brief using this structure: IMPACT ALERT — {confidence_band} Confidence ({confidence_score}%) / Anomaly Type: {anomaly_type} / Deployment: {release_version} / Affected Flow: {affected_flow} / Affected Segment: {affected_segment} / Estimated Clients: ~{affected_users_est} / SIGNALS: bullet per signal / PATTERN MATCH: {pattern_match_summary} / RECOMMENDED ACTION: {recommended_action}).";

return [{
  json: {
    anomaly_classification: prev.anomaly_classification,
    pattern_match: patternMatch,
    deployment: prev.deployment,
    deployment_id: prev.deployment_id,
    call3_user_message: userMessage,
    call3_system_prompt: systemPrompt,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key,
    anthropic_api_key: prev.anthropic_api_key
  }
}];

// Parse Call 3 and prepare Airtable write payload
const prev = $('Parse Call 2 + Prepare Call 3').item.json;
const response = $input.item.json;

const content = response.content[0].text;
let brief;

try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  brief = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Call 3 response: ' + content);
}

console.log('Call 3 complete — confidence:', brief.confidence_score, '| anomaly_type:', brief.anomaly_type);

const now = new Date().toISOString();

return [{
  json: {
    brief,
    airtable_record: {
      brief_id: brief.brief_id || `brief-${prev.deployment_id}-${Date.now()}`,
      deployment_id: prev.deployment_id,
      generated_at: now,
      confidence_score: brief.confidence_score,
      confidence_band: brief.confidence_band,
      anomaly_type: brief.anomaly_type,
      affected_flow: brief.affected_flow,
      affected_segment: brief.affected_segment,
      signal_summary: JSON.stringify(brief.signal_summary),
      pattern_match_id: prev.pattern_match.match_id || '',
      pattern_match_summary: brief.pattern_match_summary,
      recommended_action: brief.recommended_action,
      full_brief_text: brief.full_brief_text,
      pr_to_review: brief.pr_to_review || null,
      low_confidence_flag: brief.low_confidence_flag,
      human_decision: 'Pending',
      estimated_affected_users: 285000,
      status: 'pending_review'
    },
    deployment_id: prev.deployment_id,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key
  }
}];

// Find the deployment record ID to update its status
const prev = $('Parse Call 3').item.json;

return [{
  json: {
    deployment_id: prev.deployment_id,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key,
    write_result: $input.item.json
  }
}];

// Extract Airtable record ID for deployment status update
const prev = $('Prepare Status Update').item.json;
const lookupResult = $input.item.json;

if (!lookupResult.records || lookupResult.records.length === 0) {
  throw new Error('Could not find deployment record to update status');
}

const recordId = lookupResult.records[0].id;

return [{
  json: {
    record_id: recordId,
    airtable_base_id: prev.airtable_base_id,
    airtable_api_key: prev.airtable_api_key
  }
}];
